/**
 * Input: a single-line text field.
 * Purpose: every text input. Generated by shadcn, then re-themed to Grove. Owner: design system.
 * Props: invalid (sets aria-invalid), leading and trailing (an Icon, or a small control such as an
 *   IconButton, shown inside the field), every native input prop. FormField (S2-T05) wires labels,
 *   hints and error text.
 * Responsive: 52 px tall on every screen; text stays 16 px so iOS does not zoom on focus.
 * Accessibility: always paired with a Label (FormField enforces it). Set inputMode and autoComplete
 *   per field. Error state is a thicker danger border, never colour alone (the message carries it).
 *   A leading icon is decoration. A trailing control must have its own accessible name.
 * States: default, hover, focus, error, disabled, read-only.
 * Dependencies: cn. Tests: inputs.test.tsx; Design Lab "Fields" (S2-T07).
 * UX reference: ds-components, Fields (c-core.css .input, .input-wrap).
 */
import type { ComponentProps, ReactNode } from "react";
import { cn } from "@/lib/cn";

type InputProps = Omit<ComponentProps<"input">, "ref"> & {
  invalid?: boolean | undefined;
  leading?: ReactNode;
  trailing?: ReactNode;
};

function Input({ className, type, invalid, leading, trailing, ...props }: InputProps) {
  const field = (
    <input
      type={type}
      data-slot="input"
      aria-invalid={invalid || props["aria-invalid"]}
      className={cn(
        "min-h-(--size-control) w-full min-w-0 rounded-md border-[length:var(--bw-field)] border-line-input bg-surface px-4",
        "text-body font-medium text-ink placeholder:font-normal placeholder:text-subtle",
        "transition-colors duration-(--dur-fast) hover:border-primary",
        "focus-visible:border-primary focus-visible:outline-2 focus-visible:outline-offset-1",
        "aria-invalid:border-[length:var(--bw-error)] aria-invalid:border-danger",
        "read-only:border-line-strong read-only:bg-canvas-sunken read-only:text-muted",
        "disabled:cursor-not-allowed disabled:border-line-strong disabled:bg-canvas-sunken disabled:text-muted",
        leading ? "pl-10" : null,
        trailing ? "pr-10" : null,
        className,
      )}
      {...props}
    />
  );
  if (!leading && !trailing) return field;
  return (
    <div className="relative w-full" data-slot="input-wrap">
      {leading ? (
        <span className="pointer-events-none absolute top-1/2 left-3 -translate-y-1/2 text-primary">
          {leading}
        </span>
      ) : null}
      {field}
      {trailing ? (
        <span className="absolute top-1/2 right-1 -translate-y-1/2 text-muted">{trailing}</span>
      ) : null}
    </div>
  );
}

export { Input };
